{"command":"@'
import envparse
from envparse import parse_env

# Check public names
public_names = [n for n in dir(envparse) if not n.startswith("_")]
assert public_names == ["parse_env"], f"Unexpected public names: {public_names}"

# Acceptance criteria
assert parse_env("A=1\nB = 2 \n") == {"A": "1", "B": "2"}
assert parse_env("# c\n\n   \nA=1") == {"A": "1"}
assert parse_env('A="x\\ny"') == {"A": "x\ny"}
assert parse_env("A='x\\ny'") == {"A": "x\\ny"}
assert parse_env("A=hello  # trailing") == {"A": "hello"}
assert parse_env("A=a#b") == {"A": "a#b"}
assert parse_env("export FOO=bar") == {"FOO": "bar"}
assert parse_env("A=1\nA=2") == {"A": "2"}
assert parse_env("A=") == {"A": ""}
assert parse_env('A="  padded  "') == {"A": "  padded  "}
assert parse_env("URL=https://x/y?a=b") == {"URL": "https://x/y?a=b"}

# Additional edge cases
assert parse_env("") == {}
assert parse_env("A=1\r\nB=2\r\n") == {"A": "1", "B": "2"}
assert parse_env("A=1\nB=2\nA=3") == {"A": "3", "B": "2"}
assert list(parse_env("A=1\nB=2\nA=3").keys()) == ["A", "B"]
assert parse_env("export=1") == {"export": "1"}
assert parse_env("export_foo=1") == {"export_foo": "1"}
assert parse_env("  export   FOO  =  bar  ") == {"FOO": "bar"}
assert parse_env('A="\\t\\r\\"\\\\\\q"') == {"A": '\t\r"\\\\q'}
assert parse_env("A=#comment") == {"A": "#comment"}
assert parse_env("A= #comment") == {"A": ""}
assert parse_env("A=a#b # comment") == {"A": "a#b"}
assert parse_env('A="') == {"A": '"'}
assert parse_env("A='") == {"A": "'"}

# Error cases
for text, expected_msg in [
    ("A=1\nnope\n", "invalid line 2: nope"),
    ("1BAD=x", "invalid line 1: 1BAD=x"),
    ("=x", "invalid line 1: =x"),
    ("export =x", "invalid line 1: export =x"),
    ("A=1\r\nbad line\r\n", "invalid line 2: bad line"),
]:
    try:
        parse_env(text)
        assert False, f"Expected ValueError for {text!r}"
    except ValueError as e:
        assert str(e) == expected_msg, f"Got {str(e)!r}, expected {expected_msg!r}"

print("All tests passed!")
